$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
. (Join-Path $PSScriptRoot 'custom-app-production-recovery-aware-permit-transaction-finalization.ps1')

function Assert-RAFTTrue([bool]$Value,[string]$Message){if(-not $Value){throw $Message}}
function Assert-RAFTFalse([bool]$Value,[string]$Message){if($Value){throw $Message}}
function Assert-RAFTEq($Actual,$Expected,[string]$Message){if([string]$Actual -cne [string]$Expected){throw "$Message actual=<$Actual> expected=<$Expected>"}}
function Copy-RAFT($Object){return (($Object|ConvertTo-Json -Depth 60)|ConvertFrom-Json)}

$script:RAFTMode='valid';$script:RAFTFixture=$null;$script:RAFTCleanupCalls=0;$script:RAFTConsumptionCalls=0
function New-RAFTFixtureV010 {
    param([string]$Label='valid',[string]$Name='tagify')
    $base=Join-Path $env:TEMP ('raft-'+$Label+'-'+[Guid]::NewGuid().ToString('N'));$live=Join-Path $base 'live';$txn=Join-Path $base '.spotify-control-txn-11111111111111111111111111111111';$old=Join-Path $txn 'old-live';$stageWs=Join-Path $base 'stage-workspace';$stage=Join-Path $stageWs 'stage';$appBackup=Join-Path $base 'app-backup';$persistBackup=Join-Path $base 'persistence-backup';$sentinel=Join-Path $base 'unrelated-sibling'
    foreach($p in @($live,$old,$stage,$appBackup,$persistBackup,$sentinel)){[IO.Directory]::CreateDirectory($p)|Out-Null}
    [IO.File]::WriteAllText((Join-Path $live 'index.js'),'new',[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $stage 'index.js'),'new',[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $old 'index.js'),'old',[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $appBackup 'index.js'),'old',[Text.UTF8Encoding]::new($false))
    $stageHash=('2'*64);$oldHash=('8'*64);$persistHash=('9'*64);$hist=('e'*64);$current=('a'*64);$stageFp=('3'*64);$prepFp=('4'*64);$atomicFp=('5'*64);$consumption=('c'*64);$txnId=('1'*64);$binding=('f'*64)
    $stageResult=[pscustomobject]@{name=$Name;source_identity='owner/repo';transaction_id=$txnId;github_repo_id=12345;surface_kind='github';remote_commit_sha=('b'*40);consumption_id=$consumption;historical_consumption_envelope_sha256=$hist;binding_fingerprint=$binding;remote_tree_sha256=$stageHash;result_fingerprint=$stageFp}
    $prepared=[pscustomobject]@{name=$Name;source_identity='owner/repo';transaction_id=$txnId;github_repo_id=12345;surface_kind='github';remote_commit_sha=('b'*40);consumption_id=$consumption;historical_consumption_envelope_sha256=$hist;binding_fingerprint=$binding;recovery_stage_result_fingerprint=$stageFp;stage_workspace_path=$stageWs;stage_path=$stage;stage_tree_sha256=$stageHash;app_backup_path=$appBackup;app_backup_tree_sha256=$oldHash;app_backup_file_count=1;app_backup_total_bytes=3;persistence_backup_path=$persistBackup;persistence_fingerprint=$persistHash;result_fingerprint=$prepFp}
    $atomic=[pscustomobject]@{name=$Name;source_identity='owner/repo';transaction_id=$txnId;github_repo_id=12345;surface_kind='github';remote_commit_sha=('b'*40);consumption_id=$consumption;historical_consumption_envelope_sha256=$hist;current_consumption_envelope_sha256=$current;current_consumption_revision=1;binding_fingerprint=$binding;recovery_pre_apply_result_fingerprint=$prepFp;recovery_stage_result_fingerprint=$stageFp;post_runtime_tree_sha256=$stageHash;old_live_tree_sha256=$oldHash;live_path=$live;transaction_root=$txn;old_live_path=$old;preserved_git_tree_sha256=$null;persistence_fingerprint=$persistHash;result_fingerprint=$atomicFp}
    $persistence=[pscustomobject]@{receipt=[pscustomobject]@{persisted_revision=1};persisted_snapshot=[pscustomobject]@{state=[pscustomobject]@{revision=1;consumptions=@([pscustomobject]@{name=$Name;consumption_id=$consumption})}}}
    $lifecycle=[pscustomobject]@{managed_by='dynamic-spicetify-v1';present=$true;user_removed=$false;ambiguous=$false;safe_local_identity=$true;locations=@($live)}
    return [pscustomobject]@{base=$base;name=$Name;live=$live;txn=$txn;old=$old;stage_ws=$stageWs;stage=$stage;app_backup=$appBackup;persistence_backup=$persistBackup;sentinel=$sentinel;stage_hash=$stageHash;old_hash=$oldHash;persist_hash=$persistHash;historical=$hist;current=$current;atomic=$atomic;prepared=$prepared;stage_result=$stageResult;persistence=$persistence;lifecycle=$lifecycle}
}
function Remove-RAFTFixtureV010($F){if($null-ne$F -and (Test-Path -LiteralPath $F.base)){Remove-Item -LiteralPath $F.base -Recurse -Force -ErrorAction SilentlyContinue}}
function Reset-RAFTV010($F,[string]$Mode){$script:RAFTFixture=$F;$script:RAFTMode=$Mode;$script:RAFTCleanupCalls=0;$script:RAFTConsumptionCalls=0}

function Test-CustomAppProductionRecoveryAwarePermitAtomicLiveSwapResultV010 {param($Result) if($script:RAFTMode-ceq'atomic-invalid'){[pscustomobject]@{ok=$false;reason='atomic-invalid'}}else{[pscustomobject]@{ok=$true;reason='atomic-valid'}}}
function Test-CustomAppProductionRecoveryAwarePermitPreApplyPreparedResultV010 {param($Result) if($script:RAFTMode-ceq'prepared-invalid'){[pscustomobject]@{ok=$false;reason='prepared-invalid'}}else{[pscustomobject]@{ok=$true;reason='prepared-valid'}}}
function Test-CustomAppProductionRecoveryAwarePermitStageExecutorResultV010 {param($Result) if($script:RAFTMode-ceq'stage-invalid'){[pscustomobject]@{ok=$false;reason='stage-invalid'}}else{[pscustomobject]@{ok=$true;reason='stage-valid'}}}
function Assert-CustomAppAtomicSafeDirectoryV010 {param([string]$Path,[string]$Label) if(-not(Test-Path -LiteralPath $Path -PathType Container)){throw "$Label missing"};return [IO.Path]::GetFullPath($Path).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)}
function Get-CustomAppUpdateTreeSnapshotV010 {param([string]$Root) $f=$script:RAFTFixture;$full=[IO.Path]::GetFullPath($Root).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);if($full-eq[IO.Path]::GetFullPath($f.app_backup).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar) -and $script:RAFTMode-ceq'app-backup-drift'){return [pscustomobject]@{tree_sha256=('7'*64);file_count=1;total_bytes=3}};return [pscustomobject]@{tree_sha256=$f.old_hash;file_count=1;total_bytes=3}}
function Get-CustomAppLocalRuntimeBaseline {param([string]$Name,[string]$AppPath) $f=$script:RAFTFixture;$isStage=([IO.Path]::GetFullPath($AppPath)-eq[IO.Path]::GetFullPath($f.stage));if($isStage -and $script:RAFTMode-ceq'stage-runtime-drift'){return [pscustomobject]@{safe=$true;installable=$true;tree_sha256=('6'*64)}};if(-not$isStage -and $script:RAFTMode-ceq'post-live-drift' -and $script:RAFTCleanupCalls-gt0){return [pscustomobject]@{safe=$true;installable=$true;tree_sha256=('6'*64)}};return [pscustomobject]@{safe=$true;installable=$true;tree_sha256=$f.stage_hash}}
function Test-CustomAppLocalRuntimeBaselineMutationAuthority {param($Baseline) return $false}
function Get-CustomAppAtomicGitSnapshotV010 {param([string]$LivePath) return [pscustomobject]@{present=$false;tree_sha256=$null;file_count=0;total_bytes=0}}
function Test-CustomAppProductionPersistenceBackupV010 {param([string]$BackupPath,[string]$ExpectedFingerprint) if($script:RAFTMode-ceq'persistence-backup-drift' -and $script:RAFTCleanupCalls-gt0){[pscustomobject]@{ok=$false;reason='fixture-persistence-backup-drift'}}else{[pscustomobject]@{ok=$true;reason='persistence-backup-valid'}}}
function Get-SpotifyPersistenceSnapshot {param([string]$LocalAppDataRoot,[string]$AppDataRoot) $f=$script:RAFTFixture;if($script:RAFTMode-ceq'pre-persistence-drift' -and $script:RAFTCleanupCalls-eq0){return [pscustomobject]@{fingerprint=('6'*64)}};if($script:RAFTMode-ceq'post-persistence-drift' -and $script:RAFTCleanupCalls-gt0){return [pscustomobject]@{fingerprint=('6'*64)}};return [pscustomobject]@{fingerprint=$f.persist_hash}}
function Get-CustomAppProductionRecoveryAwarePermitConsumptionPersistedTargetV010 {param($AllowedRoot,$StoreDirectory,$TargetState,$TargetRevision,$ExpectedConsumptionId) $script:RAFTConsumptionCalls++;$f=$script:RAFTFixture;if($script:RAFTMode-ceq'post-consumption-fail' -and $script:RAFTConsumptionCalls-gt1){return [pscustomobject]@{ok=$false;reason='fixture-post-consumption-fail'}};$rows=@([pscustomobject]@{name=$f.name;consumption_id=('c'*64)});$rev=1;$env=$f.current;if($script:RAFTMode-ceq'same-app-newer'){$rows+= [pscustomobject]@{name=$f.name;consumption_id=('d'*64)};$rev=2;$env=('b'*64)}elseif($script:RAFTMode-ceq'unrelated-newer'){$rows+= [pscustomobject]@{name='future-app';consumption_id=('d'*64)};$rev=2;$env=('b'*64)};return [pscustomobject]@{ok=$true;reason='target-valid';target_envelope=[pscustomobject]@{envelope_sha256=$f.historical};current_envelope=[pscustomobject]@{envelope_sha256=$env};current_state=[pscustomobject]@{revision=$rev;consumptions=$rows};current_revision=$rev}}
function Remove-CustomAppProductionRecoveryAwarePermitAtomicTransactionV010 {param([string]$TransactionRoot,[string]$LivePath) $script:RAFTCleanupCalls++;if($script:RAFTMode-ceq'cleanup-fail'){return [pscustomobject]@{ok=$false;reason='fixture-cleanup-fail'}};if(Test-Path -LiteralPath $TransactionRoot){Remove-Item -LiteralPath $TransactionRoot -Recurse -Force};return [pscustomobject]@{ok=$true;reason='transaction-workspace-cleaned'}}
function Invoke-CustomAppProductionRecoveryAwarePermitTransactionFinalizationValidationHookV010 {param([string]$Checkpoint,$Context) if($script:RAFTMode-ceq'before-hook-fail' -and $Checkpoint-ceq'before-cleanup'){throw 'fixture-before-cleanup'};if($script:RAFTMode-ceq'after-hook-fail' -and $Checkpoint-ceq'after-cleanup'){throw 'fixture-after-cleanup'}}

function Invoke-RAFTV010 {param($F,[AllowNull()]$Atomic=$null,[AllowNull()]$Prepared=$null,[AllowNull()]$Stage=$null) if($null-eq$Atomic){$Atomic=$F.atomic};if($null-eq$Prepared){$Prepared=$F.prepared};if($null-eq$Stage){$Stage=$F.stage_result};Invoke-CustomAppProductionRecoveryAwarePermitTransactionFinalizationV010 -RecoveryAwareAtomicResult $Atomic -RecoveryAwarePreparedResult $Prepared -RecoveryAwareStageExecutorResult $Stage -Name $F.name -LifecycleRow $F.lifecycle -AllowedRoot (Join-Path $F.base 'allowed') -ConsumptionStoreDirectory (Join-Path $F.base 'consumption') -ConsumptionPersistenceResult $F.persistence -LocalAppDataRoot (Join-Path $F.base 'local') -AppDataRoot (Join-Path $F.base 'roaming') -Now ([DateTimeOffset]'2026-11-01T20:00:00Z')}
function Assert-RAFTNoAuthorityV010($R,[string]$Label){$x=if($R.PSObject.Properties['result'] -and $null-ne$R.result){$R.result}else{$R};foreach($p in @('result_is_authority','apply_execution_authorized','spicetify_apply_authorized','additional_mutation_authorized','live_destination_authorized','production_execution_authorized','production_mutation_authorized')){Assert-RAFTFalse ([bool]$x.$p) "$Label escaped $p"}}

$count=0
$f=New-RAFTFixtureV010 'valid';try{Reset-RAFTV010 $f 'valid';$r=Invoke-RAFTV010 $f;Assert-RAFTTrue ([bool]$r.ok) ('valid denied: '+[string]$r.reason);Assert-RAFTEq $script:RAFTCleanupCalls 1 'valid cleanup count';Assert-RAFTEq $script:RAFTConsumptionCalls 2 'valid consumption revalidation count';Assert-RAFTFalse (Test-Path -LiteralPath $f.txn) 'valid transaction remained';Assert-RAFTTrue (Test-Path -LiteralPath $f.sentinel -PathType Container) 'valid unrelated sibling deleted';foreach($p in @($f.stage_ws,$f.stage,$f.app_backup,$f.persistence_backup)){Assert-RAFTTrue (Test-Path -LiteralPath $p -PathType Container) "valid preserved evidence missing $p"};Assert-RAFTNoAuthorityV010 $r 'valid';$check=Test-CustomAppProductionRecoveryAwarePermitTransactionFinalizationResultV010 $r.result;Assert-RAFTTrue ([bool]$check.ok) ('valid result check failed: '+[string]$check.reason);$tamper=Copy-RAFT $r.result;$tamper.production_mutation_authorized=$true;$tamper.result_fingerprint=Get-CustomAppProductionRecoveryAwarePermitTransactionFinalizationSha256V010 (Get-CustomAppProductionRecoveryAwarePermitTransactionFinalizationResultMaterialV010 $tamper);$tc=Test-CustomAppProductionRecoveryAwarePermitTransactionFinalizationResultV010 $tamper;Assert-RAFTFalse ([bool]$tc.ok) 'rehashed authority escape accepted';$count+=2}finally{Remove-RAFTFixtureV010 $f}

foreach($case in @('atomic-invalid','prepared-invalid','stage-invalid','same-app-newer','before-hook-fail','cleanup-fail','pre-persistence-drift','stage-runtime-drift')){$f=New-RAFTFixtureV010 $case;try{Reset-RAFTV010 $f $case;$r=Invoke-RAFTV010 $f;Assert-RAFTFalse ([bool]$r.ok) "$case unexpectedly succeeded";Assert-RAFTNoAuthorityV010 $r $case;Assert-RAFTTrue (Test-Path -LiteralPath $f.txn -PathType Container) "$case deleted transaction before safe finalization";$count++}finally{Remove-RAFTFixtureV010 $f}}

$f=New-RAFTFixtureV010 'unrelated-newer';try{Reset-RAFTV010 $f 'unrelated-newer';$r=Invoke-RAFTV010 $f;Assert-RAFTTrue ([bool]$r.ok) ('unrelated newer denied: '+[string]$r.reason);Assert-RAFTEq $r.result.current_consumption_revision 2 'unrelated newer revision not retained';Assert-RAFTNoAuthorityV010 $r 'unrelated-newer';$count++}finally{Remove-RAFTFixtureV010 $f}

foreach($case in @('after-hook-fail','post-live-drift','post-persistence-drift','persistence-backup-drift','post-consumption-fail')){$f=New-RAFTFixtureV010 $case;try{Reset-RAFTV010 $f $case;$r=Invoke-RAFTV010 $f;Assert-RAFTFalse ([bool]$r.ok) "$case unexpectedly succeeded";Assert-RAFTTrue ([bool]$r.transaction_workspace_deleted) "$case did not report deleted transaction";Assert-RAFTTrue ([bool]$r.requires_recovery_if_post_cleanup_validation_fails) "$case lost recovery requirement";Assert-RAFTFalse (Test-Path -LiteralPath $f.txn) "$case transaction remained";Assert-RAFTNoAuthorityV010 $r $case;$count++}finally{Remove-RAFTFixtureV010 $f}}

$f=New-RAFTFixtureV010 'extra-entry';try{[IO.File]::WriteAllText((Join-Path $f.txn 'unexpected.txt'),'x',[Text.UTF8Encoding]::new($false));Reset-RAFTV010 $f 'valid';$r=Invoke-RAFTV010 $f;Assert-RAFTFalse ([bool]$r.ok) 'extra txn entry accepted';Assert-RAFTTrue ([string]$r.reason -like '*contents-not-exact-old-live-only*') ('extra entry reason '+[string]$r.reason);Assert-RAFTEq $script:RAFTCleanupCalls 0 'extra entry reached cleanup';$count++}finally{Remove-RAFTFixtureV010 $f}

$f=New-RAFTFixtureV010 'app-backup-drift';try{Reset-RAFTV010 $f 'app-backup-drift';$r=Invoke-RAFTV010 $f;Assert-RAFTFalse ([bool]$r.ok) 'app backup drift accepted';Assert-RAFTTrue ([string]$r.reason -like '*app-backup-byte-drift*') ('app backup drift reason '+[string]$r.reason);Assert-RAFTEq $script:RAFTCleanupCalls 0 'app backup drift reached cleanup';$count++}finally{Remove-RAFTFixtureV010 $f}

Write-Host "CUSTOM_APP_PRODUCTION_RECOVERY_AWARE_PERMIT_TRANSACTION_FINALIZATION_SYNTHETIC_MATRIX_PASS total=$count cleanup_preconditions=true post_cleanup_recovery=true zero_authority=true"